        [UnitySetUp]public IEnumerator Setup()
        {
            concurrentInventory=false;Time.timeScale=1;Application.runInBackground=true;previousDevices=InputSystem.actions.devices;keyboard=InputSystem.AddDevice<Keyboard>();mouse=InputSystem.AddDevice<Mouse>();InputSystem.actions.devices=new InputDevice[]{keyboard,mouse};keyboard.MakeCurrent();mouse.MakeCurrent();EditorSceneManager.LoadSceneInPlayMode("Assets/IronRequiem/Scenes/CombatPolishLab.unity",new LoadSceneParameters(LoadSceneMode.Single));yield return null;yield return null;
            bot=Object.FindAnyObjectByType<BigBotCombat>();enemy=bot.GetComponent<EnemyController>();enemy.PatrolPath=null;player=Object.FindAnyObjectByType<PlayerCharacterController>();player.GetComponent<Health>().Invincible=true;MovePlayer(new Vector3(0,.03f,-12));enemy.NavMeshAgent.Warp(new Vector3(0,0,10));enemy.DetectionModule.KnownTargetTimeout=0;yield return new WaitForSeconds(.15f);enemy.DetectionModule.KnownTargetTimeout=8;EditorWindow.GetWindow(typeof(EditorWindow).Assembly.GetType("UnityEditor.GameView")).Focus();Cursor.lockState=CursorLockMode.Locked;
