        void MovePlayer(Vector3 p){var cc=player.GetComponent<CharacterController>();cc.enabled=false;player.transform.SetPositionAndRotation(p,Quaternion.identity);cc.enabled=true;player.CharacterVelocity=Vector3.zero;Physics.SyncTransforms();}
        IEnumerator Until(System.Func<bool> predicate,float seconds,string reason){float end=Time.time+seconds;while(!predicate()&&Time.time<end)yield return null;Assert.That(predicate(),Is.True,reason);}
        [UnityTearDown]public IEnumerator Cleanup(){Time.timeScale=1;var old=SceneManager.GetActiveScene();SceneManager.SetActiveScene(SceneManager.CreateScene("PolishCleanup"+Time.frameCount));yield return SceneManager.UnloadSceneAsync(old);InputSystem.actions.devices=previousDevices;InputSystem.RemoveDevice(keyboard);InputSystem.RemoveDevice(mouse);Cursor.lockState=CursorLockMode.None;yield return null;}
        IEnumerator Tap(Key key){InputSystem.QueueStateEvent(keyboard,new KeyboardState(key));yield return null;yield return null;InputSystem.QueueStateEvent(keyboard,new KeyboardState());yield return null;}
        void MeleeArena()
        {
            enemy.NavMeshAgent.Warp(new Vector3(-10,0,12));bot.transform.rotation=Quaternion.Euler(0,180,0);enemy.enabled=false;bot.GetComponent<EnemyMobile>().enabled=false;enemy.NavMeshAgent.isStopped=true;
        }
        void Contact(Vector3 outward,float gap)
        {
            Physics.SyncTransforms();var box=bot.GetComponent<BoxCollider>();var ray=new Ray(new Vector3(box.bounds.center.x,1.62f,box.bounds.center.z)+outward*10,-outward);Assert.That(box.Raycast(ray,out var hit,20),Is.True);var p=hit.point+outward*gap;p.y=.03f;MovePlayer(p);player.transform.rotation=Quaternion.LookRotation(-outward);Physics.SyncTransforms();
        }
        string MeleeDiagnostics()
        {
            var camera=player.PlayerCamera.transform;var box=bot.GetComponent<BoxCollider>();var origin=camera.position;var tip=origin+camera.forward*player.GetComponent<ProtagonistMelee>().Reach;var colliders=Physics.OverlapCapsule(origin,tip,.18f,-1,QueryTriggerInteraction.Ignore);var point=box.ClosestPoint(origin);var delta=point-origin;
            return " origin="+origin+" forward="+camera.forward+" player="+player.transform.position+" bot="+bot.transform.position+" distance="+delta.magnitude+" health="+bot.GetComponent<Damageable>().Health+" invincible="+bot.GetComponent<Health>().Invincible+" overlaps="+string.Join(",",colliders.Select(c=>c.name+":"+c.GetComponentInParent<Damageable>()+":"+c.transform.IsChildOf(player.transform)))+" ray="+string.Join(",",Physics.RaycastAll(origin,delta.normalized,delta.magnitude+.002f,-1,QueryTriggerInteraction.Ignore).Select(h=>h.collider.name+":"+h.distance));
        }
        [UnityTest]public IEnumerator MeleeContactAngles()
        {
            MeleeArena();var health=bot.GetComponent<Health>();var melee=player.GetComponent<ProtagonistMelee>();var log=new List<string>();
            for(int side=0;side<8;side++)
            {
                float angle=side*Mathf.PI/4;Contact(new Vector3(Mathf.Sin(angle),0,Mathf.Cos(angle)),.4f);float before=health.CurrentHealth;int serial=melee.AttackSerial;yield return Tap(Key.F);yield return new WaitForSeconds(.65f);log.Add(side+" damage="+(before-health.CurrentHealth)+" serial="+(melee.AttackSerial-serial)+" hits="+melee.LastHitCount);Assert.That(melee.AttackSerial,Is.EqualTo(serial+1));System.IO.File.WriteAllLines("Tools/IronRequiem/Reports/CombatPolish/melee-contact.txt",log);Assert.That(health.CurrentHealth,Is.EqualTo(before-melee.Damage),"Contact angle "+side+MeleeDiagnostics());
            }
            // Reproduce a giant kinematic collider enclosing the camera near its corner.
            player.enabled=false;var bounds=bot.GetComponent<BoxCollider>().bounds;MovePlayer(new Vector3(bounds.max.x-.04f,.03f,bounds.max.z-.04f));player.transform.rotation=Quaternion.LookRotation(Vector3.ProjectOnPlane(bounds.center-player.PlayerCamera.transform.position,Vector3.up));Physics.SyncTransforms();float insideBefore=health.CurrentHealth;yield return Tap(Key.F);yield return new WaitForSeconds(.65f);log.Add("inside corner damage="+(insideBefore-health.CurrentHealth));System.IO.File.WriteAllLines("Tools/IronRequiem/Reports/CombatPolish/melee-contact.txt",log);Assert.That(health.CurrentHealth,Is.EqualTo(insideBefore-melee.Damage),"Contact inside large collider cannot be rejected using distance to its centre");
        }
        [UnityTest]public IEnumerator MeleeTimingWallAndRange()
        {
            MeleeArena();Contact(Vector3.back,.5f);var health=bot.GetComponent<Health>();var melee=player.GetComponent<ProtagonistMelee>();int events=0;health.OnDamaged+=(v,o)=>events++;float before=health.CurrentHealth;InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.F));yield return new WaitForSeconds(.17f);Assert.That(health.CurrentHealth,Is.EqualTo(before),"Damage only at impact");yield return new WaitForSeconds(.8f);InputSystem.QueueStateEvent(keyboard,new KeyboardState());yield return null;Assert.That(events,Is.EqualTo(1));Assert.That(health.CurrentHealth,Is.EqualTo(before-melee.Damage));
            var wall=GameObject.CreatePrimitive(PrimitiveType.Cube);wall.transform.position=player.PlayerCamera.transform.position+player.PlayerCamera.transform.forward*.22f;wall.transform.localScale=new Vector3(.9f,1,.08f);Physics.SyncTransforms();before=health.CurrentHealth;yield return Tap(Key.F);yield return new WaitForSeconds(.65f);Assert.That(health.CurrentHealth,Is.EqualTo(before),"Wall blocks fist");Object.Destroy(wall);yield return null;Contact(Vector3.back,3);yield return Tap(Key.F);yield return new WaitForSeconds(.65f);Assert.That(health.CurrentHealth,Is.EqualTo(before),"Original melee range remains unchanged");Assert.That(melee.Reach,Is.EqualTo(1.55f));Assert.That(melee.Damage,Is.EqualTo(25));
        }
        [UnityTest]public IEnumerator PunchCutStaysOutsideWeaponCamera()
        {
            var hands=player.GetComponent<ProtagonistHandsPresentation>();var melee=player.GetComponent<ProtagonistMelee>();var manager=player.GetComponent<PlayerWeaponsManager>();var forearm=hands.FpsRoot.GetComponentsInChildren<Transform>(true).Single(t=>t.name=="Forearm_L");var hand=hands.FpsRoot.GetComponentsInChildren<Transform>(true).Single(t=>t.name=="Hand_L");var renderer=hands.FpsRoot.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="Forearm_L_FPS");var mesh=new Mesh();renderer.BakeMesh(mesh,false);var axis=(hand.position-forearm.position).normalized;var scale=renderer.transform.lossyScale;var initial=mesh.vertices;var projections=initial.Select(v=>Vector3.Dot(renderer.transform.TransformPoint(new Vector3(v.x/scale.x,v.y/scale.y,v.z/scale.z))-forearm.position,axis)).ToArray();float min=projections.Min();var cap=Enumerable.Range(0,initial.Length).Where(i=>projections[i]<min+.025f).ToArray();float length=Vector3.Distance(hand.position,forearm.position);int frames=0;int visibleCut=0;bool sawFist=false;var finger=hands.FpsRoot.GetComponentsInChildren<Transform>(true).Single(t=>t.name=="Index2_L");var rest=finger.localRotation;
            InputSystem.QueueStateEvent(keyboard,new KeyboardState(Key.F));yield return null;yield return null;InputSystem.QueueStateEvent(keyboard,new KeyboardState());
            while(melee.IsAttacking)
            {
                yield return new WaitForEndOfFrame();if(!melee.IsAttacking)break;frames++;renderer.BakeMesh(mesh,false);var vertices=mesh.vertices;scale=renderer.transform.lossyScale;
                foreach(int i in cap){var world=renderer.transform.TransformPoint(new Vector3(vertices[i].x/scale.x,vertices[i].y/scale.y,vertices[i].z/scale.z));var view=manager.WeaponCamera.WorldToViewportPoint(world);if(view.z>manager.WeaponCamera.nearClipPlane&&view.x>=0&&view.x<=1&&view.y>=0&&view.y<=1)visibleCut++;}
                Assert.That(Vector3.Distance(hand.position,forearm.position),Is.EqualTo(length).Within(.001f),"Arm proportions stay constant");sawFist|=Quaternion.Angle(rest,finger.localRotation)>12;
                if(frames==2||frames==6||frames==11)ScreenCapture.CaptureScreenshot("Tools/IronRequiem/Reports/CombatPolish/punch-"+frames+".png");
            }
            Object.Destroy(mesh);Assert.That(cap.Length,Is.GreaterThan(3));Assert.That(frames,Is.GreaterThan(5));Assert.That(visibleCut,Is.Zero,"Proximal cut must remain outside FPS camera for entire attack");Assert.That(sawFist,Is.True);Assert.That(hands.LeftHandVisible,Is.False);Assert.That(melee.Reach,Is.EqualTo(1.55f));System.IO.File.WriteAllText("Tools/IronRequiem/Reports/CombatPolish/arm-framing.txt","frames="+frames+" cap vertices="+cap.Length+" visible cut samples="+visibleCut+" forearm length="+length);
        }
        [UnityTest]public IEnumerator PistolMountAndBalance()
        {
            var manager=player.GetComponent<PlayerWeaponsManager>();var hands=player.GetComponent<ProtagonistHandsPresentation>();yield return new WaitForSeconds(.6f);var weapon=manager.GetActiveWeapon();var original=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/IronRequiem/Prefabs/Weapons/Weapon_IR_Pistol.prefab").GetComponent<WeaponController>();
            Assert.That(weapon.SourcePrefab.name,Is.EqualTo("Weapon_IR_Pistol_CombatPolish"));Assert.That(hands.CurrentRepresentation,Is.EqualTo(ProtagonistHandsPresentation.Representation.Pistol));Assert.That(hands.RightHandVisible,Is.False);
            foreach(var field in typeof(WeaponController).GetFields(System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.Instance))if(field.Name!="WeaponRoot"&&field.Name!="WeaponMuzzle"&&field.Name!="WeaponAnimator"&&field.FieldType!=typeof(UnityEngine.Events.UnityAction))Assert.That(field.GetValue(weapon),Is.EqualTo(field.GetValue(original)),"Balance/reference "+field.Name);
            var attachment=weapon.GetComponentsInChildren<Transform>(true).Single(t=>t.name=="Attachment");var wrist=hands.FpsRoot.GetComponentsInChildren<Transform>(true).Single(t=>t.name=="Hand_R");int shots=0;weapon.OnShoot+=()=>shots++;
            for(int phase=0;phase<3;phase++){
                InputSystem.QueueStateEvent(mouse,new MouseState{buttons=(ushort)(phase==1?2:phase==2?1:0)});InputSystem.QueueStateEvent(keyboard,new KeyboardState(phase==1?Key.W:Key.None));float until=Time.time+.6f;
                while(Time.time<until){yield return new WaitForEndOfFrame();Assert.That(Vector3.Distance(wrist.position,attachment.position+weapon.WeaponMuzzle.forward*.003f),Is.LessThan(.002f));Assert.That(Vector3.Angle(weapon.WeaponMuzzle.forward,attachment.forward),Is.LessThan(.1f));}
                ScreenCapture.CaptureScreenshot("Tools/IronRequiem/Reports/CombatPolish/pistol-"+phase+".png");
            }
            Assert.That(shots,Is.GreaterThan(0));InputSystem.QueueStateEvent(mouse,new MouseState());InputSystem.QueueStateEvent(keyboard,new KeyboardState());Assert.That(Vector3.Distance(weapon.transform.InverseTransformPoint(weapon.WeaponMuzzle.position),new Vector3(0,.124f,.456f)),Is.LessThan(.0001f));
        }
        [UnityTest]public IEnumerator EnemiesReadableWithoutLights()
        {
            var ambient=RenderSettings.ambientLight;var mode=RenderSettings.ambientMode;RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=Color.black;var lights=Object.FindObjectsByType<Light>();foreach(var light in lights)light.enabled=false;var cam=new GameObject("DarkReadabilityCamera").AddComponent<Camera>();cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=Color.black;cam.cullingMask=1<<29;cam.fieldOfView=38;var rt=new RenderTexture(192,192,24);cam.targetTexture=rt;var tex=new Texture2D(192,192,TextureFormat.RGB24,false);var log=new List<string>();
            // Deterministic order (2026-11-04): runtime-added presentation components change instance-id order; HoverBot first reads dim.
            foreach(var actor in Object.FindObjectsByType<EnemyController>().OrderBy(a=>a.name)){
                actor.enabled=false;var mobile=actor.GetComponent<EnemyMobile>();if(mobile)mobile.enabled=false;actor.NavMeshAgent.isStopped=true;foreach(var canvas in actor.GetComponentsInChildren<Canvas>(true))canvas.gameObject.SetActive(false);foreach(var r in actor.GetComponentsInChildren<Renderer>(true))if(!(r is ParticleSystemRenderer))r.gameObject.layer=29;
                var indicator=actor.GetComponent<EnemyPowerIndicators>();var turret=actor.GetComponent<EnemyTurret>();if(turret)turret.enabled=false;var eye=actor.GetComponentsInChildren<Renderer>().FirstOrDefault(r=>r.sharedMaterials.Contains(actor.EyeColorMaterial));var centre=indicator?indicator.Indicators[0].bounds.center:eye.bounds.center;var forward=indicator?actor.transform.forward:actor.GetCurrentWeapon().WeaponMuzzle.forward;cam.transform.position=centre+forward*5;cam.transform.LookAt(centre);yield return new WaitForEndOfFrame();cam.Render();var old=RenderTexture.active;RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,192,192),0,0);tex.Apply();RenderTexture.active=old;int lit=tex.GetPixels().Count(p=>Mathf.Max(p.r,p.g,p.b)>.35f);log.Add(actor.name+" lit="+lit);System.IO.File.WriteAllBytes("Tools/IronRequiem/Reports/CombatPolish/dark-"+actor.name+".png",tex.EncodeToPNG());Assert.That((indicator?indicator.Indicators[0].sharedMaterial:actor.EyeColorMaterial).IsKeywordEnabled("_EMISSION"),Is.True);Assert.That(lit,Is.GreaterThan(8),actor.name+" must remain readable without lights");if(indicator){Assert.That(indicator.Indicators[0].sharedMaterial.name,Is.EqualTo("RobotStatus_Amber"));Assert.That(indicator.Indicators[0].GetComponent<Collider>(),Is.Null);}foreach(var t in actor.GetComponentsInChildren<Transform>(true))t.gameObject.layer=0;
            }
            Assert.That(log.Count,Is.EqualTo(4));System.IO.File.WriteAllLines("Tools/IronRequiem/Reports/CombatPolish/dark-readability.txt",log);cam.targetTexture=null;Object.Destroy(rt);Object.Destroy(tex);Object.Destroy(cam.gameObject);RenderSettings.ambientLight=ambient;RenderSettings.ambientMode=mode;
        }
        [UnityTest]public IEnumerator CoordinatedVisualDeaths()
        {
