            var body=bot.GetComponent<BigBotDestruction>();int shots=bot.ShotsFired;float health=player.GetComponent<Health>().CurrentHealth;int created=RobotDestructionPool.CreatedBursts;var pool=Object.FindObjectsByType<RobotBodyBurst>(FindObjectsInactive.Include);Assert.That(pool.Length,Is.EqualTo(16));foreach(var burst in pool){Assert.That(burst.GetComponentInChildren<DamageArea>(true),Is.Null);Assert.That(burst.GetComponentInChildren<CannonExplosion>(true),Is.Null);Assert.That(burst.GetComponentsInChildren<Light>(true).Length,Is.Zero);}
            foreach(var actor in actors){var hp=actor.GetComponent<Health>();hp.TakeDamage(hp.MaxHealth+1,null);hp.TakeDamage(hp.MaxHealth+1,null);}yield return null;
            Assert.That(body.DeathCount,Is.EqualTo(1));Assert.That(RobotDestructionPool.BurstsInUse,Is.EqualTo(3));Assert.That(body.DeathBurstCount,Is.Zero);Assert.That(body.DeathStarted,Is.True);
            yield return new WaitForSeconds(1.4f);Assert.That(body.DeathBurstCount,Is.EqualTo(1));Assert.That(bot.ShotsFired,Is.EqualTo(shots));Assert.That(RobotDestructionPool.BurstsInUse,Is.EqualTo(4));Assert.That(RobotBodyBurst.AudioVoices,Is.LessThanOrEqualTo(4));Assert.That(stolen,Is.Not.Null);Assert.That(stolen.State,Is.EqualTo(StolenCannonState.Available));Assert.That(Vector3.Distance(stolen.transform.position,modulePosition),Is.LessThan(.01f));ScreenCapture.CaptureScreenshot("Tools/IronRequiem/Reports/CombatPolish/death-simultaneous.png");
            yield return new WaitForSeconds(3.1f);Assert.That(RobotDestructionPool.BurstsInUse,Is.Zero);Assert.That(RobotBodyBurst.AudioVoices,Is.Zero);Assert.That(RobotDestructionPool.CreatedBursts,Is.EqualTo(created));foreach(var burst in pool){Assert.That(burst.transform.localScale,Is.EqualTo(Vector3.one));foreach(var ps in burst.Layers)Assert.That(ps.IsAlive(true),Is.False);}
            int callbacks=0;Assert.That(RobotDestructionPool.Burst(null,player.transform.position+player.transform.forward*4,()=>callbacks++,1),Is.True);yield return new WaitForSeconds(.35f);Assert.That(callbacks,Is.EqualTo(1));yield return new WaitForSeconds(3);Assert.That(callbacks,Is.EqualTo(1));Assert.That(RobotDestructionPool.BurstsInUse,Is.Zero);Assert.That(player.GetComponent<Health>().CurrentHealth,Is.EqualTo(health));
        }
