        [UnityTest]public IEnumerator TurnTransitions()
        {
            enemy.NavMeshAgent.Warp(new Vector3(-10,0,12));bot.transform.rotation=Quaternion.Euler(0,180,0);enemy.NavMeshAgent.isStopped=true;var feet=bot.GetComponentsInChildren<Transform>(true).Where(t=>t.name=="Foot_L"||t.name=="Foot_R").OrderBy(t=>t.name).ToArray();var plant=bot.GetComponent<BigBotTurnFootPlant>();var previous=feet.Select(f=>f.position).ToArray();float previousYaw=bot.transform.eulerAngles.y,maxJump=0,plantedDistance=0,plantedTime=0,angle=180;int shots=bot.ShotsFired;float start=Time.time;
            while(Time.time-start<10)
            {
                float elapsed=Time.time-start;float direction=elapsed<2?1:elapsed<4?-1:elapsed<5?0:elapsed<7?1:elapsed<8?0:-1;angle+=direction*65*Time.deltaTime;float radians=angle*Mathf.Deg2Rad;MovePlayer(new Vector3(-10+Mathf.Sin(radians)*7,.03f,12+Mathf.Cos(radians)*7));player.transform.rotation=Quaternion.LookRotation(Vector3.ProjectOnPlane(bot.transform.position-player.transform.position,Vector3.up));yield return new WaitForEndOfFrame();
                float yaw=bot.transform.eulerAngles.y;Assert.That(Mathf.Abs(Mathf.DeltaAngle(previousYaw,yaw))/Mathf.Max(Time.deltaTime,.001f),Is.LessThan(75));previousYaw=yaw;
                for(int i=0;i<2;i++){float delta=Vector3.Distance(feet[i].position,previous[i]);if(elapsed>1)maxJump=Mathf.Max(maxJump,delta);if(plant&&plant.Stabilizing&&plant.SwingingFoot!=i&&elapsed>1){plantedDistance+=Vector3.ProjectOnPlane(feet[i].position-previous[i],Vector3.up).magnitude;plantedTime+=Time.deltaTime;}previous[i]=feet[i].position;}
                if(elapsed>3&&elapsed<3.1f)ScreenCapture.CaptureScreenshot("Tools/IronRequiem/Reports/CombatPolish/turn-reversal.png");
            }
            string label=plant?"fixed":"baseline";System.IO.File.WriteAllText("Tools/IronRequiem/Reports/CombatPolish/turn-"+label+".txt","max per-frame foot motion="+maxJump+"; planted slip="+(plantedTime>0?plantedDistance/plantedTime:0)+"; shots="+(bot.ShotsFired-shots)+"; root motion="+bot.Presentation.Animator.applyRootMotion+"; agent rotation="+enemy.NavMeshAgent.updateRotation);
            Assert.That(bot.Presentation.Animator.applyRootMotion,Is.False);Assert.That(enemy.NavMeshAgent.updateRotation,Is.False);Assert.That(bot.ShotsFired,Is.GreaterThan(shots),"Combat must continue during turning");
            if(plant){Assert.That(maxJump,Is.LessThan(.11f),"No foot teleport across reversals/stops");Assert.That(plantedTime,Is.GreaterThan(1));Assert.That(plantedDistance/plantedTime,Is.LessThan(.12f));}
        }
    }
}
